using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;using AirBridge.Routing;
class PhoneAB {
 public class Saved {public Graph LastRunningGraph; }public class Graph {public GraphEdge[] Edges;}
 static int Main(string[] args){try{var saved=new JavaScriptSerializer().Deserialize<Saved>(File.ReadAllText(args[0]));var edges=saved.LastRunningGraph.Edges.Where(e=>e.Source.StartsWith("p:")&&e.Target.StartsWith("o:")).ToArray();if(edges.Select(e=>e.Source).Distinct().Count()!=2)throw new Exception("Expected two direct phone sources");Directory.CreateDirectory(args[1]);PhoneWorkerClient.DiagnosticPath=Path.Combine(args[1],"phone-ab.log");var type=Assembly.LoadFrom(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"AirBridge.exe")).GetType("AirBridge.Desktop.AudioExperiment");var enabled=type.GetField("Enabled",BindingFlags.Public|BindingFlags.Static);enabled.SetValue(null,true);var experiment=Activator.CreateInstance(type,true);var tick=type.GetMethod("Tick");
 using(var engine=new GraphRuntime()){engine.TakeOverNativePlayback=false;engine.AppRoutingJournal=Path.Combine(args[1],"app-recovery.xml");engine.DefaultRoutingJournal=Path.Combine(args[1],"default-recovery.xml");engine.ApplyAsync(GraphPlan.Create(edges,new ModuleSpec[0])).GetAwaiter().GetResult();Console.WriteLine("Both phone channels opened; six-phase comparison started.");var end=DateTime.UtcNow.AddMinutes(6);while((bool)enabled.GetValue(null)&&DateTime.UtcNow<end){tick.Invoke(experiment,new object[]{engine,args[1]});Thread.Sleep(500);}if((bool)enabled.GetValue(null))throw new TimeoutException("Test did not finish within six minutes");}Console.WriteLine("Released test channels.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex.GetBaseException().Message);return 1;}}
}
